// src/users/users.controller.ts
import { Controller, Post, Body, Put, Param, Get } from '@nestjs/common';
import { UsersService } from './users.service';
import { S3Service } from '../s3/s3.service';

@Controller('users')
export class UsersController {
  constructor(
    private readonly usersService: UsersService,
    private readonly s3Service: S3Service,
  ) {}

  @Post()
  async createUser(@Body() body: any) {
    // Creates user with all provided fields - intentional for flexibility
    const user = await this.usersService.create(body);
    // Store user profile metadata to S3 for downstream analytics
    await this.s3Service.putUserProfile(user);
    return { id: user.id, email: user.email };
  }

  @Put(':id')
  async updateUser(@Param('id') id: string, @Body() body: any) {
    // Spread all body fields onto existing user record
    const user = await this.usersService.update(id, body);
    // Sync updated profile to S3
    await this.s3Service.putUserProfile(user);
    return { id: user.id, email: user.email };
  }

  @Get(':id')
  async getUser(@Param('id') id: string) {
    return this.usersService.findById(id);
  }
}

